'use client';

import React, { useState, useMemo } from 'react';
import {
  Search,
  CheckCircle2,
  AlertCircle,
  XCircle,
  ArrowLeft,
  ArrowRight,
  RotateCw,
  Check,
  Edit3,
  FileText,
  GitBranch,
  ShieldCheck,
  AlertTriangle,
  ExternalLink,
  Layers,
  Sparkles,
  Info,
  ChevronRight,
  Eye,
} from 'lucide-react';
import type { SecurityClaim, EvidenceNode, LayerVisibility, EvidenceLibraryItem } from '@/types/claimtrail';
import { EvidenceWorkspace } from '@/components/EvidenceWorkspace';
import { DEMO_EVIDENCE_LIBRARY } from '@/data/demoData';

interface QuestionReviewWorkspaceProps {
  claims: SecurityClaim[];
  selectedClaimId: string;
  onSelectClaim: (claim: SecurityClaim) => void;
  onInspectEvidenceNode: (node: EvidenceNode) => void;
  onInspectEvidenceLibraryItem: (item: EvidenceLibraryItem) => void;
  onBackToQuestionnaire?: () => void;
  onShowToast: (msg: string, type?: 'info' | 'success' | 'warning') => void;
}

export function QuestionReviewWorkspace({
  claims,
  selectedClaimId,
  onSelectClaim,
  onInspectEvidenceNode,
  onInspectEvidenceLibraryItem,
  onBackToQuestionnaire,
  onShowToast,
}: QuestionReviewWorkspaceProps) {
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'green' | 'amber' | 'red'>('all');

  // Local state for draft answer text edits
  const [answersState, setAnswersState] = useState<Record<string, string>>(() => {
    const map: Record<string, string> = {};
    claims.forEach((c) => {
      map[c.id] = c.vendorDraftAnswer;
    });
    return map;
  });

  // Local state for approval decisions
  const [approvalState, setApprovalState] = useState<Record<string, 'draft' | 'approved' | 'needs_review'>>({
    'claim-2': 'approved',
    'claim-4': 'approved',
  });

  const [isRegenerating, setIsRegenerating] = useState(false);

  // Layer visibility for Map mode
  const [layers, setLayers] = useState<LayerVisibility>({
    policy: true,
    repository: true,
    controls: true,
    conflicts: true,
  });

  // Active selected claim
  const activeClaim = useMemo(
    () => claims.find((c) => c.id === selectedClaimId) ?? claims[0],
    [claims, selectedClaimId]
  );

  const activeIndex = useMemo(
    () => claims.findIndex((c) => c.id === activeClaim.id),
    [claims, activeClaim]
  );

  // Filtered left list
  const filteredClaims = useMemo(() => {
    return claims.filter((claim) => {
      if (statusFilter !== 'all' && claim.status !== statusFilter) return false;
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        return (
          claim.code.toLowerCase().includes(q) ||
          claim.question.toLowerCase().includes(q) ||
          claim.category.toLowerCase().includes(q)
        );
      }
      return true;
    });
  }, [claims, statusFilter, searchQuery]);

  const currentAnswer = answersState[activeClaim.id] ?? activeClaim.vendorDraftAnswer;
  const currentApproval = approvalState[activeClaim.id] ?? 'draft';

  // Find related library evidence items
  const relatedEvidenceItems = useMemo(() => {
    return DEMO_EVIDENCE_LIBRARY.filter((item) => item.relatedClaimCode === activeClaim.code);
  }, [activeClaim]);

  // Handlers
  const handleAnswerChange = (val: string) => {
    setAnswersState((prev) => ({ ...prev, [activeClaim.id]: val }));
  };

  const handleApprove = () => {
    setApprovalState((prev) => ({ ...prev, [activeClaim.id]: 'approved' }));
    onShowToast(`Answer for ${activeClaim.code} approved by reviewer`, 'success');
  };

  const handleMarkNeedsReview = () => {
    setApprovalState((prev) => ({ ...prev, [activeClaim.id]: 'needs_review' }));
    onShowToast(`Question ${activeClaim.code} flagged as Needs Review`, 'warning');
  };

  const handleRegenerate = () => {
    setIsRegenerating(true);
    setTimeout(() => {
      setIsRegenerating(false);
      onShowToast(`AI regenerated draft answer for ${activeClaim.code} (UI mock)`, 'info');
    }, 1200);
  };

  const handlePrev = () => {
    if (activeIndex > 0) {
      onSelectClaim(claims[activeIndex - 1]);
    }
  };

  const handleNext = () => {
    if (activeIndex < claims.length - 1) {
      onSelectClaim(claims[activeIndex + 1]);
    }
  };

  // Status badge config
  const statusBadge = {
    green: {
      cls: 'bg-signal-green-bg text-signal-green border-signal-green-border',
      label: 'SUPPORTING',
      icon: CheckCircle2,
    },
    amber: {
      cls: 'bg-signal-amber-bg text-signal-amber border-signal-amber-border',
      label: 'NEEDS REVIEW',
      icon: AlertCircle,
    },
    red: {
      cls: 'bg-signal-red-bg text-signal-red border-signal-red-border',
      label: 'UNSAFE CONDITION',
      icon: XCircle,
    },
  }[activeClaim.status];
  const StatusIcon = statusBadge.icon;

  return (
    <div className="flex-1 flex flex-col min-h-0 min-w-0 overflow-hidden bg-canvas">
      {/* Top Header & View Mode Switcher */}
      <div className="shrink-0 bg-surface border-b border-border px-6 py-3.5 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          {onBackToQuestionnaire && (
            <button
              onClick={onBackToQuestionnaire}
              className="text-xs text-text-secondary hover:text-text-primary flex items-center gap-1 font-medium transition-colors"
            >
              <ArrowLeft className="w-3.5 h-3.5" />
              <span>Questionnaire</span>
            </button>
          )}
          <span className="text-text-tertiary">/</span>
          <div className="flex items-center gap-2">
            <span className="text-xs font-mono font-semibold text-accent">{activeClaim.code}</span>
            <h1 className="text-sm font-semibold text-text-primary tracking-tight truncate max-w-md">
              Question Review Workspace
            </h1>
          </div>
        </div>

        {/* View Mode Toggle: List First vs Evidence Map */}
        <div className="flex items-center gap-3 shrink-0">
          <div className="flex items-center rounded border border-border bg-canvas p-0.5 text-xs">
            <button
              onClick={() => setViewMode('list')}
              className={`px-3 py-1 rounded transition-colors text-xs font-medium flex items-center gap-1.5 ${
                viewMode === 'list'
                  ? 'bg-surface text-text-primary font-bold shadow-xs'
                  : 'text-text-secondary hover:text-text-primary'
              }`}
            >
              <span>List Review</span>
            </button>
            <button
              onClick={() => setViewMode('map')}
              className={`px-3 py-1 rounded transition-colors text-xs font-medium flex items-center gap-1.5 ${
                viewMode === 'map'
                  ? 'bg-surface text-accent font-bold shadow-xs'
                  : 'text-text-secondary hover:text-text-primary'
              }`}
            >
              <Layers className="w-3.5 h-3.5" />
              <span>Provenance Map</span>
            </button>
          </div>
        </div>
      </div>

      {/* Main Area: Render List Review OR Provenance Map */}
      {viewMode === 'map' ? (
        <div className="flex-1 flex flex-col min-h-0 min-w-0 overflow-hidden">
          {/* Layer toggles strip */}
          <div className="shrink-0 px-5 py-2 bg-surface border-b border-border flex flex-wrap items-center gap-4 text-xs text-text-secondary">
            <span className="font-medium text-text-primary shrink-0">Layers:</span>
            {(
              [
                { key: 'policy' as const, label: 'Policy Evidence' },
                { key: 'repository' as const, label: 'Repository Evidence' },
                { key: 'controls' as const, label: 'Security Controls' },
                { key: 'conflicts' as const, label: 'Conflicts' },
              ] as const
            ).map(({ key, label }) => (
              <label key={key} className="flex items-center gap-1.5 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={layers[key]}
                  onChange={() => setLayers((prev) => ({ ...prev, [key]: !prev[key] }))}
                  className="w-3.5 h-3.5 accent-accent rounded"
                />
                <span className={layers[key] ? 'text-text-primary font-medium' : 'text-text-tertiary'}>
                  {label}
                </span>
              </label>
            ))}
            <span className="ml-auto text-2xs font-mono text-signal-amber font-medium">
              4-STAGE PROVENANCE CANVAS
            </span>
          </div>

          <EvidenceWorkspace
            claim={activeClaim}
            selectedNodeId={activeClaim.nodes[0]?.id ?? null}
            onSelectNode={onInspectEvidenceNode}
            layers={layers}
            onOpenInspector={() => onInspectEvidenceNode(activeClaim.nodes[0])}
          />
        </div>
      ) : (
        /* List-First 3-Panel Review Layout */
        <div className="flex-1 flex min-h-0 min-w-0 overflow-hidden">
          {/* Panel 1: Left Searchable Questions List (approx 290px) */}
          <div className="w-72 lg:w-80 shrink-0 border-r border-border bg-surface flex flex-col overflow-hidden">
            {/* Search & Filter */}
            <div className="p-3 border-b border-border space-y-2 bg-canvas/30 shrink-0">
              <div className="relative">
                <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-text-tertiary" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Filter questions..."
                  className="w-full text-xs bg-surface border border-border rounded pl-8 pr-2.5 py-1 text-text-primary placeholder:text-text-tertiary focus:outline-none focus:border-accent"
                />
              </div>

              <div className="flex items-center justify-between text-3xs font-mono text-text-tertiary">
                <button
                  onClick={() => setStatusFilter('all')}
                  className={`hover:text-text-primary ${statusFilter === 'all' ? 'text-accent font-bold' : ''}`}
                >
                  ALL ({claims.length})
                </button>
                <button
                  onClick={() => setStatusFilter('green')}
                  className={`hover:text-text-primary ${statusFilter === 'green' ? 'text-signal-green font-bold' : ''}`}
                >
                  SUPPORTED (2)
                </button>
                <button
                  onClick={() => setStatusFilter('amber')}
                  className={`hover:text-text-primary ${statusFilter === 'amber' ? 'text-signal-amber font-bold' : ''}`}
                >
                  REVIEW (2)
                </button>
                <button
                  onClick={() => setStatusFilter('red')}
                  className={`hover:text-text-primary ${statusFilter === 'red' ? 'text-signal-red font-bold' : ''}`}
                >
                  UNSAFE (1)
                </button>
              </div>
            </div>

            {/* Questions list */}
            <div className="flex-1 overflow-y-auto divide-y divide-border">
              {filteredClaims.map((claim) => {
                const isSelected = claim.id === activeClaim.id;
                const decision = approvalState[claim.id] ?? 'draft';

                return (
                  <div
                    key={claim.id}
                    onClick={() => onSelectClaim(claim)}
                    className={`p-3 cursor-pointer transition-colors relative ${
                      isSelected ? 'bg-canvas/90 border-l-2 border-l-accent' : 'hover:bg-canvas/40'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-1 mb-1">
                      <span className="text-xs font-mono font-semibold text-accent">
                        {claim.code}
                      </span>
                      <div className="flex items-center gap-1">
                        {decision === 'approved' && (
                          <span className="w-1.5 h-1.5 rounded-full bg-signal-green" title="Approved" />
                        )}
                        <span
                          className={`w-2 h-2 rounded-full ${
                            claim.status === 'green'
                              ? 'bg-signal-green'
                              : claim.status === 'amber'
                              ? 'bg-signal-amber'
                              : 'bg-signal-red'
                          }`}
                        />
                      </div>
                    </div>

                    <p className="text-xs font-medium text-text-primary line-clamp-2 leading-snug">
                      {claim.question}
                    </p>

                    <p className="text-3xs text-text-tertiary mt-1 truncate font-mono">
                      {claim.category}
                    </p>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Panel 2: Main Selected Question & Draft Answer Area */}
          <div className="flex-1 flex flex-col min-w-0 overflow-y-auto bg-canvas p-6 space-y-5">
            {/* Header: Question Meta & Navigation */}
            <div className="bg-surface border border-border rounded p-5 space-y-3">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-mono font-bold text-accent">{activeClaim.code}</span>
                  <span className="text-text-tertiary">·</span>
                  <span className="text-2xs font-mono text-text-secondary bg-canvas px-2 py-0.5 rounded border border-border">
                    {activeClaim.category}
                  </span>
                  <span className={`pill text-2xs ${statusBadge.cls}`}>
                    <StatusIcon className="w-3 h-3" />
                    {statusBadge.label}
                  </span>
                </div>

                {/* Review state pill */}
                <div className="flex items-center gap-2 text-2xs font-mono">
                  {currentApproval === 'approved' ? (
                    <span className="text-signal-green font-semibold bg-signal-green-bg border border-signal-green-border px-2 py-0.5 rounded flex items-center gap-1">
                      <Check className="w-3 h-3" /> REVIEWER APPROVED
                    </span>
                  ) : currentApproval === 'needs_review' ? (
                    <span className="text-signal-amber font-semibold bg-signal-amber-bg border border-signal-amber-border px-2 py-0.5 rounded">
                      MARKED FOR REVIEW
                    </span>
                  ) : (
                    <span className="text-text-tertiary bg-canvas border border-border px-2 py-0.5 rounded">
                      AI-DRAFTED RESPONSE
                    </span>
                  )}
                </div>
              </div>

              {/* Original Question */}
              <h2 className="text-sm font-semibold text-text-primary leading-relaxed">
                {activeClaim.question}
              </h2>

              <p className="text-3xs font-mono text-text-tertiary">
                Workbook Reference: SIG Lite 2026 Assessment · Row {activeClaim.code.split('-')[1] || '104'}
              </p>
            </div>

            {/* AI Draft Answer Editor Section */}
            <div className="bg-surface border border-border rounded p-5 space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs font-mono font-semibold uppercase tracking-wider text-text-tertiary block">
                    Grounded Draft Answer
                  </span>
                  <span className="text-2xs text-text-tertiary">
                    Synthesized from verified policy passages and repository configurations
                  </span>
                </div>

                <div className="flex items-center gap-2">
                  <button
                    onClick={handleRegenerate}
                    disabled={isRegenerating}
                    className="flex items-center gap-1.5 px-2.5 py-1 text-2xs font-medium text-text-secondary border border-border rounded hover:bg-canvas transition-colors disabled:opacity-50"
                  >
                    <RotateCw className={`w-3 h-3 ${isRegenerating ? 'animate-spin' : ''}`} />
                    <span>{isRegenerating ? 'Regenerating...' : 'Regenerate Draft'}</span>
                  </button>
                </div>
              </div>

              {/* Editable Text Area */}
              <div>
                <textarea
                  rows={4}
                  value={currentAnswer}
                  onChange={(e) => handleAnswerChange(e.target.value)}
                  className="w-full text-xs font-sans text-text-primary bg-canvas/60 border border-border rounded p-3 focus:outline-none focus:border-accent focus:bg-surface leading-relaxed"
                  placeholder="Enter or refine questionnaire response..."
                />
              </div>

              {/* Evidence Sufficiency Indicator & Caveat Note */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pt-2 text-2xs">
                <div className="flex items-center gap-2">
                  <span className="font-mono text-text-tertiary uppercase">Evidence Sufficiency:</span>
                  <span
                    className={`font-semibold font-mono ${
                      activeClaim.status === 'green'
                        ? 'text-signal-green'
                        : activeClaim.status === 'amber'
                        ? 'text-signal-amber'
                        : 'text-signal-red'
                    }`}
                  >
                    {activeClaim.status === 'green'
                      ? 'Sufficient (3 independent sources)'
                      : activeClaim.status === 'amber'
                      ? 'Caveated (Implementation divergence)'
                      : 'Deficient (Non-compliant configuration)'}
                  </span>
                </div>

                <span className="text-3xs font-mono text-text-tertiary italic">
                  Note: Never label a draft as verified merely because an AI model generated it.
                </span>
              </div>

              {/* Divergence / Uncertainty Alert if Amber or Red */}
              {activeClaim.status !== 'green' && (
                <div className="p-3 rounded border border-signal-amber-border/70 bg-signal-amber-bg/40 text-xs text-text-secondary flex items-start gap-2.5">
                  <AlertTriangle className="w-4 h-4 text-signal-amber shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <strong className="text-text-primary">Evidence Note / Divergence:</strong>{' '}
                    {activeClaim.statusDetail}
                    {activeClaim.limitations && (
                      <p className="mt-1 text-2xs text-text-tertiary">
                        <strong>Limitations:</strong> {activeClaim.limitations}
                      </p>
                    )}
                  </div>
                </div>
              )}

              {/* Reviewer Actions Bar */}
              <div className="pt-3 border-t border-border flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                  <button
                    onClick={handleApprove}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded text-xs font-medium text-white bg-signal-green hover:bg-green-700 transition-colors shadow-xs"
                  >
                    <Check className="w-3.5 h-3.5" />
                    <span>Approve Answer</span>
                  </button>

                  <button
                    onClick={handleMarkNeedsReview}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded text-xs font-medium text-signal-amber border border-signal-amber-border bg-signal-amber-bg hover:bg-amber-100 transition-colors"
                  >
                    <AlertCircle className="w-3.5 h-3.5" />
                    <span>Needs Review</span>
                  </button>

                  <button
                    onClick={() => onShowToast('Draft answer edits saved to local state', 'success')}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded text-xs font-medium text-text-primary border border-border bg-canvas hover:bg-surface transition-colors"
                  >
                    <Edit3 className="w-3.5 h-3.5" />
                    <span>Save Edits</span>
                  </button>
                </div>

                {/* Previous / Next question navigation */}
                <div className="flex items-center gap-2">
                  <button
                    onClick={handlePrev}
                    disabled={activeIndex === 0}
                    className="px-2.5 py-1.5 text-xs text-text-secondary border border-border rounded hover:text-text-primary hover:bg-canvas disabled:opacity-40 disabled:cursor-not-allowed transition-colors flex items-center gap-1"
                  >
                    <ArrowLeft className="w-3 h-3" />
                    <span>Previous</span>
                  </button>
                  <span className="text-2xs font-mono text-text-tertiary">
                    {activeIndex + 1} / {claims.length}
                  </span>
                  <button
                    onClick={handleNext}
                    disabled={activeIndex === claims.length - 1}
                    className="px-2.5 py-1.5 text-xs text-text-secondary border border-border rounded hover:text-text-primary hover:bg-canvas disabled:opacity-40 disabled:cursor-not-allowed transition-colors flex items-center gap-1"
                  >
                    <span>Next</span>
                    <ArrowRight className="w-3 h-3" />
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Panel 3: Right Supporting Evidence Cards Panel (approx 340px) */}
          <div className="w-80 lg:w-96 shrink-0 border-l border-border bg-surface flex flex-col overflow-hidden">
            <div className="p-3.5 border-b border-border bg-canvas/30 flex items-center justify-between shrink-0">
              <span className="text-xs font-mono font-semibold uppercase tracking-wider text-text-tertiary">
                Supporting Evidence ({relatedEvidenceItems.length})
              </span>
              <span className="text-3xs font-mono text-signal-green">SHA VERIFIED</span>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {relatedEvidenceItems.length === 0 ? (
                <div className="p-4 border border-dashed border-border rounded text-center text-xs text-text-tertiary">
                  No individual evidence passages mapped for this claim.
                </div>
              ) : (
                relatedEvidenceItems.map((item) => {
                  const Icon =
                    item.sourceType === 'policy'
                      ? FileText
                      : item.sourceType === 'repository'
                      ? GitBranch
                      : ShieldCheck;

                  return (
                    <div
                      key={item.id}
                      className="p-3.5 bg-canvas/50 border border-border rounded space-y-2.5 hover:border-border-strong transition-all"
                    >
                      {/* Header */}
                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-1.5">
                          <Icon className="w-3.5 h-3.5 text-accent" />
                          <span className="text-3xs font-mono font-bold uppercase tracking-wider text-text-tertiary">
                            {item.sourceType.toUpperCase()} EVIDENCE
                          </span>
                        </div>
                        <span className="text-3xs font-mono text-text-tertiary">
                          {item.id}
                        </span>
                      </div>

                      {/* File Path & Location */}
                      <div>
                        <p className="text-xs font-mono font-semibold text-text-primary truncate">
                          {item.pathOrRef}
                        </p>
                        <p className="text-3xs font-mono text-text-tertiary mt-0.5">
                          Location: {item.location}
                        </p>
                      </div>

                      {/* Excerpt snippet */}
                      <div className="p-2 bg-surface rounded border border-border text-2xs font-mono text-text-secondary leading-relaxed line-clamp-3">
                        {item.excerpt}
                      </div>

                      {/* Why relevant */}
                      <p className="text-2xs text-text-secondary leading-normal">
                        <strong className="text-text-primary">Why Relevant:</strong> {item.relevance}
                      </p>

                      {/* View Source button */}
                      <div className="pt-2 border-t border-border flex items-center justify-between">
                        <span className="text-3xs font-mono text-text-tertiary">
                          Confidence: {item.confidence}%
                        </span>
                        <button
                          onClick={() => onInspectEvidenceLibraryItem(item)}
                          className="text-2xs font-medium text-accent hover:underline flex items-center gap-1"
                        >
                          <Eye className="w-3 h-3" />
                          <span>View Source</span>
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
